<script setup>
import {computed} from 'vue';import {number,percent,s} from './store';
const props=defineProps({rows:{type:Array,default:()=>[]},title:String,pie:Boolean,table:Boolean,mobile:Boolean});
const columns=[{key:'label',label:'Nhóm'},{key:'count',label:'Đăng ký',align:'right'},{key:'percent',label:'Tỷ lệ',align:'right'}];
const chart=computed(()=>{const rows=props.rows.slice(0,20);const common={tooltip:{renderMode:'richText',confine:true,trigger:'item',formatter:p=>`${p.name}: ${number(p.value)} (${percent(rows[p.dataIndex]?.percent)})`},aria:{enabled:true},animation:false};return props.pie?{...common,legend:{type:'scroll',bottom:0},series:[{type:'pie',radius:['35%','65%'],center:['50%','43%'],data:rows.map(r=>({name:r.label,value:r.count})),label:{show:s.showPercent,position:'inside',formatter:p=>percent(rows[p.dataIndex]?.percent)},labelLayout:{hideOverlap:true}}]}:{...common,grid:{left:8,right:s.showPercent?62:16,top:16,bottom:16,containLabel:true},xAxis:{type:'value',axisLabel:{hideOverlap:true,formatter:number}},yAxis:{type:'category',inverse:true,data:rows.map(r=>r.label),axisLabel:{hideOverlap:true,width:props.mobile?100:170,overflow:'truncate'}},series:[{type:'bar',barMaxWidth:28,data:rows.map(r=>r.count),label:{show:s.showPercent,position:'right',formatter:p=>percent(rows[p.dataIndex]?.percent)},labelLayout:{hideOverlap:true}}]};});
</script><template><section class="card chart-wrap"><h3>{{title}}</h3><MEmptyState v-if="!rows.length" type="no-result" title="Không có dữ liệu phù hợp" /><template v-else><MChart v-if="!table" :option="chart" :height="Math.max(300,pie?300:Math.min(rows.length*38+50,650))" :aria-label="title" /><div v-else-if="mobile" class="mobile-list"><article v-for="r in rows" :key="r.label" class="row justify-between"><span>{{r.label}}</span><strong>{{number(r.count)}} · {{percent(r.percent)}}</strong></article></div><div v-else class="report-table"><MDataTable :columns="columns" :rows="rows" row-key="label" :page-size="rows.length" :total="rows.length"><template #cell-count="{row}">{{number(row.count)}}</template><template #cell-percent="{row}">{{percent(row.percent)}}</template></MDataTable></div><p v-if="!table&&rows.length>20" class="muted">Hiển thị 20 nhóm đầu. Xem đầy đủ trong bảng số liệu hoặc file Excel.</p><div v-if="!table" class="row muted"><span v-for="r in rows.slice(0,20)" :key="r.label">{{r.label}}: {{number(r.count)}} · {{percent(r.percent)}}</span></div></template></section></template>
